import axios from 'axios';

const API_URL = 'http://localhost:8000/api/businesses';

/**
 * Fetch all businesses with optional filtering
 * 
 * @param {Object} params - Query parameters
 * @param {number} params.skip - Number of businesses to skip for pagination
 * @param {number} params.limit - Maximum number of businesses to return
 * @param {string} params.name - Filter businesses by name
 * @param {number} params.min_rating - Filter businesses by minimum rating
 * @param {number} params.max_rating - Filter businesses by maximum rating
 * @param {string} params.sort_by_rating - Sort businesses by rating ('asc' or 'desc')
 * @returns {Promise} Promise with response data
 */
const getAllBusinesses = async (params = {}) => {
  try {
    const response = await axios.get(API_URL, { params });
    return response.data;
  } catch (error) {
    throw error;
  }
};

/**
 * Fetch a single business by ID
 * 
 * @param {number} id - Business ID
 * @returns {Promise} Promise with response data
 */
const getBusinessById = async (id) => {
  try {
    const response = await axios.get(`${API_URL}/${id}`);
    return response.data;
  } catch (error) {
    throw error;
  }
};

/**
 * Create a new business
 * 
 * @param {Object} businessData - Business data
 * @returns {Promise} Promise with response data
 */
const createBusiness = async (businessData) => {
  try {
    const response = await axios.post(API_URL, businessData);
    return response.data;
  } catch (error) {
    throw error;
  }
};

/**
 * Update an existing business
 * 
 * @param {number} id - Business ID
 * @param {Object} businessData - Business data to update
 * @returns {Promise} Promise with response data
 */
const updateBusiness = async (id, businessData) => {
  try {
    const response = await axios.put(`${API_URL}/${id}`, businessData);
    return response.data;
  } catch (error) {
    throw error;
  }
};

/**
 * Delete a business
 * 
 * @param {number} id - Business ID
 * @returns {Promise} Promise with response data
 */
const deleteBusiness = async (id) => {
  try {
    const response = await axios.delete(`${API_URL}/${id}`);
    return response.data;
  } catch (error) {
    throw error;
  }
};

/**
 * Get ratings for a business
 * 
 * @param {number} businessId - Business ID
 * @param {Object} params - Query parameters
 * @param {number} params.skip - Number of ratings to skip
 * @param {number} params.limit - Maximum number of ratings to return
 * @returns {Promise} Promise with response data
 */
const getBusinessRatings = async (businessId, params = {}) => {
  try {
    const response = await axios.get(`${API_URL}/${businessId}/ratings`, { params });
    return response.data;
  } catch (error) {
    throw error;
  }
};

/**
 * Add or update a rating for a business
 * 
 * @param {number} businessId - Business ID
 * @param {Object} ratingData - Rating data
 * @returns {Promise} Promise with response data
 */
const addOrUpdateRating = async (businessId, ratingData) => {
  try {
    const response = await axios.post(`${API_URL}/${businessId}/ratings`, ratingData);
    return response.data;
  } catch (error) {
    throw error;
  }
};

/**
 * Delete a rating for a business
 * 
 * @param {number} businessId - Business ID
 * @returns {Promise} Promise with response data
 */
const deleteRating = async (businessId) => {
  try {
    await axios.delete(`${API_URL}/${businessId}/ratings/me`);
    return true;
  } catch (error) {
    throw error;
  }
};

const businessService = {
  getAllBusinesses,
  getBusinessById,
  createBusiness,
  updateBusiness,
  deleteBusiness,
  getBusinessRatings,
  addOrUpdateRating,
  deleteRating
};

export default businessService;
